import 'jest';
import { Queue } from '../../src';

describe('Queue', () => {
    test('can add a single item', () => {
        const queue = new Queue<number>();
        expect(queue.isEmpty).toBe(true);
        queue.enqueue(10);
        expect(queue.isEmpty).toBe(false);
    });

    test('can add multiple items', () => {
        const queue = new Queue<number>();
        expect(queue.length).toBe(0);
        queue.enqueue(10);
        queue.enqueue(100);
        queue.enqueue(1000);
        expect(queue.length).toBe(3);
    });

    test('dequeue returns first item in queue', () => {
        const queue = new Queue<number>();
        queue.enqueue(1989);
        queue.enqueue(1998);
        queue.enqueue(2001);

        expect(queue.dequeue()).toBe(1989);
        expect(queue.dequeue()).toBe(1998);
        expect(queue.dequeue()).toBe(2001);
        expect(queue.dequeue()).toBe(undefined);
    });

    test('peek correctly returns the first item in the queue without removing it', () => {
        const queue = new Queue<number>();
        expect(queue.length).toBe(0);
        expect(queue.peek()).toBe(undefined);

        queue.enqueue(1989);
        queue.enqueue(1998);
        queue.enqueue(2001);

        expect(queue.peek()).toBe(1989);
        expect(queue.peek()).toBe(1989);
        expect(queue.length).toBe(3);
    });

    test('clear correctly empties the queue', () => {
        const queue = new Queue<number>();
        queue.enqueue(0);
        queue.enqueue(1);
        queue.enqueue(2);
        expect(queue.length).toBe(3);
        expect(queue.isEmpty).toBe(false);

        queue.clear();
        expect(queue.length).toBe(0);
        expect(queue.isEmpty).toBe(true);
    });
});